package main

import "fmt"

type Matrix struct {
    rows, cols int
    data       [][]float64
}

func NewMatrix(rows, cols int) *Matrix {
    data := make([][]float64, rows)
    for i := range data {
        data[i] = make([]float64, cols)
    }
    return &Matrix{rows, cols, data}
}

// 矩阵乘法：O(n³)
func Mul(a, b *Matrix) *Matrix {
    if a.cols != b.rows {
        panic("维度不匹配")
    }
    c := NewMatrix(a.rows, b.cols)
    for i := 0; i < a.rows; i++ {
        for j := 0; j < b.cols; j++ {
            for k := 0; k < a.cols; k++ {
                c.data[i][j] += a.data[i][k] * b.data[k][j]
            }
        }
    }
    return c
}

// 转置
func Transpose(a *Matrix) *Matrix {
    b := NewMatrix(a.cols, a.rows)
    for i := 0; i < a.rows; i++ {
        for j := 0; j < a.cols; j++ {
            b.data[j][i] = a.data[i][j]
        }
    }
    return b
}

func main() {
    // 2x2 矩阵乘法
    a := &Matrix{2, 2, [][]float64{{1, 2}, {3, 4}}}
    b := &Matrix{2, 2, [][]float64{{5, 6}, {7, 8}}}
    c := Mul(a, b)
    fmt.Println(c.data)  // [[19 22] [43 50]]
}

package main

import (
    "fmt"
    "math"
)

// 高斯消元解 Ax = b，返回解向量 x
// augmented: n x (n+1) 增广矩阵 [A|b]
func gaussianElimination(aug [][]float64) []float64 {
    n := len(aug)
    for col := 0; col < n; col++ {
        // 选主元（部分主元法，减少数值误差）
        maxRow := col
        for r := col + 1; r < n; r++ {
            if math.Abs(aug[r][col]) > math.Abs(aug[maxRow][col]) {
                maxRow = r
            }
        }
        aug[col], aug[maxRow] = aug[maxRow], aug[col]

        pivot := aug[col][col]
        if math.Abs(pivot) < 1e-10 {
            continue  // 奇异矩阵
        }

        // 消元
        for r := col + 1; r < n; r++ {
            factor := aug[r][col] / pivot
            for j := col; j <= n; j++ {
                aug[r][j] -= factor * aug[col][j]
            }
        }
    }

    // 回代
    x := make([]float64, n)
    for i := n - 1; i >= 0; i-- {
        x[i] = aug[i][n]
        for j := i + 1; j < n; j++ {
            x[i] -= aug[i][j] * x[j]
        }
        x[i] /= aug[i][i]
    }
    return x
}

func main() {
    // 解方程组：x + 2y = 5，3x + 4y = 6
    aug := [][]float64{
        {1, 2, 5},
        {3, 4, 6},
    }
    x := gaussianElimination(aug)
    fmt.Printf("x=%.1f, y=%.1f\n", x[0], x[1])  // x=-4.0, y=4.5
}
